234		if err := lExp.SetStatus("M-EXP", StatusRetired); err == nil {
235			t.Fatal("写盘失败应返回保存错误")
236		}
237		d, _ := lExp.CanUse("M-EXP")
238		if d.Allowed || !containsReason(d.Reasons, "到期") || containsReason(d.Reasons, "停用") {
239			t.Fatalf("失败停用不得替换证书到期原因：allowed=%v reasons=%v", d.Allowed, d.Reasons)
240		}
241	
242		// 在用 + 无证书：切换待校准失败后仍只因无证书被拒，不能出现待校准原因。
243		lNone := newTestLedger(t, clock)
244		mustRegister(t, lNone, "M-NONE", "万用表", 0.5)
245		if err := lNone.SetStatus("M-NONE", StatusInUse); err != nil {
246			t.Fatalf("set in-use: %v", err)
247		}
248		blockSaving(t, lNone)
249		if err := lNone.SetStatus("M-NONE", StatusPending); err == nil {
250			t.Fatal("写盘失败应返回保存错误")
251		}
252		d, _ = lNone.CanUse("M-NONE")
253		if d.Allowed || !containsReason(d.Reasons, "没有校准证书") ||
254			containsReason(d.Reasons, "待校准") {
255			t.Fatalf("失败的待校准切换不得增加状态原因：allowed=%v reasons=%v", d.Allowed, d.Reasons)
256		}
257	}
