333		mustAddCert(t, l, CertificateInput{
334			InstrumentID: "M-1", Number: "C-1", CalDate: "2026-01-01",
335			Expiry: "2026-10-02", Method: "m", Error: 0.1, Summary: "s",
336		})
337		_ = l.SetStatus("M-1", StatusInUse)
338	
339		d, _ := l.RequestUse("M-1")
