560	func containsReason(reasons []string, sub string) bool {
561		for _, r := range reasons {
562			if strings.Contains(r, sub) {
563				return true
564			}
565		}
566		return false
567	}
568	
569	func sameReasons(a, b []string) bool {
570		if len(a) != len(b) {
571			return false
572		}
573		for i := range a {
574			if a[i] != b[i] {
575				return false
576			}
577		}
578		return true
579	}
