	args := certArgs(target, "C-9", "2026-09-01", "比较法", "例行")
	// 去掉 --summary 的值，让标志悬在末尾。
	args = args[:len(args)-1]
	r := runArgs(t, args...)
	if r.code != 2 {
		t.Fatalf("末尾缺值应退出 2，得到 %d", r.code)
	}
	rv := runArgs(t, "review", "--id", "M-1", "-f", target, "--json")
